package nir.com.neonvegasslots;
import static org.junit.Assert.*;import org.robolectric.annotation.GraphicsMode;import java.lang.reflect.*;import org.junit.*;import org.junit.runner.RunWith;import org.robolectric.*;import org.robolectric.annotation.*;
@RunWith(RobolectricTestRunner.class) @Config(sdk=34) public class WinCounterTest{
 void set(SlotsView v,String n,long x)throws Exception{Field f=SlotsView.class.getDeclaredField(n);f.setAccessible(true);f.setLong(v,x);}
 @Test public void counterRisesAndSettlesWithoutChangingPaidBalance()throws Exception{SlotsView v=new SlotsView(RuntimeEnvironment.getApplication());set(v,"lastWin",1234);set(v,"winStartAt",1000);long b=v.getBalance();assertEquals(0,v.displayedLastWin(1000));assertTrue(v.displayedLastWin(1250)>0);assertTrue(v.displayedLastWin(1250)<v.displayedLastWin(1750));assertEquals(1234,v.displayedLastWin(2100));assertEquals(1234,v.displayedLastWin(9000));assertEquals(b,v.getBalance());}
 @Test public void payoutClassificationAndCreditAgreeAtEveryCounterStep()throws Exception{assertFalse(SlotsView.profitable(9,10));assertFalse(SlotsView.profitable(10,10));assertTrue(SlotsView.profitable(11,10));SlotsView v=new SlotsView(RuntimeEnvironment.getApplication());v.restore("540;1;0;0;0;1;0");set(v,"lastWin",50);set(v,"winCreditBase",490);set(v,"winStartAt",1000);for(int dt=0;dt<=1100;dt+=50)assertEquals(490+v.displayedLastWin(1000+dt),v.creditedWinBalance(1000+dt));assertEquals(540,v.getBalance());}
 @Test public void spinCreditsOnlyEvaluatedPayoutAndNoTrophyCoins()throws Exception{SlotsView v=new SlotsView(RuntimeEnvironment.getApplication());v.restore("500;0;1;0;0;1;0");java.lang.reflect.Method spin=SlotsView.class.getDeclaredMethod("spin"),finish=SlotsView.class.getDeclaredMethod("finishSpin");spin.setAccessible(true);finish.setAccessible(true);spin.invoke(v);assertEquals(490,v.getBalance());int[][] grid={{1,2,3,4,5},{0,0,0,2,1},{5,4,3,2,1}};Field g=SlotsView.class.getDeclaredField("grid");g.setAccessible(true);g.set(v,grid);long payout=SlotsView.evaluate(grid,10,null);finish.invoke(v);assertEquals(payout,v.getLastWin());assertEquals(490+payout,v.getBalance());}
 @org.robolectric.annotation.GraphicsMode(org.robolectric.annotation.GraphicsMode.Mode.NATIVE) @Test public void counterFrame()throws Exception{SlotsView v=new SlotsView(RuntimeEnvironment.getApplication());v.layout(0,0,640,1040);long n=System.currentTimeMillis();set(v,"lastWin",100);set(v,"winStartAt",n-400);set(v,"winFlashUntil",n+1200);android.graphics.Bitmap b=android.graphics.Bitmap.createBitmap(640,1040,android.graphics.Bitmap.Config.ARGB_8888);v.draw(new android.graphics.Canvas(b));try(java.io.FileOutputStream f=new java.io.FileOutputStream("/tmp/renders/neonvegasslots-smallwin-counter.png")){b.compress(android.graphics.Bitmap.CompressFormat.PNG,100,f);}} @GraphicsMode(GraphicsMode.Mode.NATIVE) @Test public void returnAndProfitFrames()throws Exception{for(int amount:new int[]{10,50}){SlotsView v=new SlotsView(RuntimeEnvironment.getApplication());v.restore("540;1;1;0;0;1;0");v.layout(0,0,420,850);long n=System.currentTimeMillis();set(v,"lastWin",amount);set(v,"winStartAt",n-400);set(v,"winCreditBase",540-amount);set(v,"winFlashUntil",n+1200);android.graphics.Bitmap b=android.graphics.Bitmap.createBitmap(420,850,android.graphics.Bitmap.Config.ARGB_8888);v.draw(new android.graphics.Canvas(b));try(java.io.FileOutputStream f=new java.io.FileOutputStream("/tmp/renders/neonvegasslots-payout-"+amount+".png")){b.compress(android.graphics.Bitmap.CompressFormat.PNG,100,f);}}}

}
